import{printedArtwork}from'../../modeling/artwork.js';const front=new URL('./source-vector-front.png',import.meta.url).href,back=new URL('./source-vector-back.png',import.meta.url).href;
/** Two matching U164 original outlined product labels rasterized;private vector originals excluded. */
export function addStickers(host){return[...(printedArtwork(host,{target:host.acMeasureAssembly.frontCarrier,url:front,size:[16,26.5],position:[0,2.75,3.855],face:'front',depth:.13,name:'AC Measure front original product label raster',artworkKind:'source-vector-raster'})??[]),...(printedArtwork(host,{target:host.acMeasureAssembly.backCarrier,url:back,size:[16,36],position:[0,6,-3.855],face:'back',depth:.13,name:'AC Measure rear original product label raster',artworkKind:'source-vector-raster'})??[])];}
